// src/App.jsx
import { useState } from 'react';
import Display from './components/Display';
import Button from './components/Button';

// Define our button layout in a 2D array for clarity
const buttonLayout = [
  ['C', 'DEL', '%', '/'],
  ['7', '8', '9', '*'],
  ['4', '5', '6', '-'],
  ['1', '2', '3', '+'],
  ['0', '.', '=']
];

export default function App() {
  const [input, setInput] = useState('');
  const [result, setResult] = useState('');

  const handleButtonClick = (value) => {
    if (value === '=') {
      // Calculate result - we'll improve this logic later
      try {
        // A safer alternative to eval for basic operations
        const calcResult = Function('"use strict";return (' + input + ')')();
        setResult(calcResult.toString());
        setInput(calcResult.toString()); // Show result, ready for next operation
      } catch (error) {
        setResult('Error');
      }
    } else if (value === 'C') {
      // Clear everything
      setInput('');
      setResult('');
    } else if (value === 'DEL') {
      // Delete the last character
      setInput((prev) => prev.slice(0, -1));
    } else {
      // Append the clicked value to the input
      setInput((prev) => prev + value);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 to-gray-700 flex items-center justify-center p-4">
      <div className="bg-gray-800 p-6 rounded-3xl shadow-2xl w-full max-w-xs">
        <Display value={input || result || '0'} />
        <div className="grid grid-cols-4 gap-3 mt-4">
          {buttonLayout.flat().map((btn) => (
            <Button 
              key={btn} 
              value={btn} 
              onClick={() => handleButtonClick(btn)}
              // Span the '0' and '=' buttons for better layout
              className={btn === '0' ? 'col-span-2' : btn === '=' ? 'col-span-2 bg-orange-500 hover:bg-orange-400' : ''}
            />
          ))}
        </div>
      </div>
    </div>
  );
}

// src/components/Button.jsx - Updated to handle onClick and className props
export default function Button({ value, onClick, className = '' }) {
  // Determine button style based on value
  const isOperator = ['/', '*', '-', '+', '='].includes(value);
  const isFunction = ['C', 'DEL', '%'].includes(value);

  let bgColor = 'bg-gray-700';
  if (isOperator) bgColor = 'bg-orange-500 hover:bg-orange-400';
  if (isFunction) bgColor = 'bg-gray-600 hover:bg-gray-500';

  return (
    <button 
      onClick={onClick}
      className={`${bgColor} text-white text-xl font-medium p-4 rounded-2xl transition-colors duration-200 active:scale-95 ${className}`}
    >
      {value}
    </button>
  );
}

// src/utils/calculate.js

export const calculate = (input) => {
  // Remove any spaces and validate input
  const expression = input.replace(/\s+/g, '');

  // Basic validation: expression should only contain numbers, operators, and decimal point
  if (!/^[\d+\-*/.()]+$/.test(expression)) {
    throw new Error('Invalid characters');
  }

  // Use a safer evaluation method
  try {
    // This is a simple approach. For a more robust solution, consider a library like 'mathjs' or 'expr-eval'.
    // We're using Function constructor but in a more controlled way than eval.
    const result = Function('"use strict";return (' + expression + ')')();

    // Handle division by zero and other edge cases
    if (!isFinite(result)) {
      throw new Error('Invalid operation');
    }

    return result.toString();
  } catch (error) {
    throw new Error('Calculation error');
  }
};

// src/App.jsx - Update the handleButtonClick function
import { calculate } from './utils/calculate';

// Inside the App component, update the handleButtonClick function:
const handleButtonClick = (value) => {
  if (value === '=') {
    if (!input) return; // Don't calculate if input is empty
    try {
      const calcResult = calculate(input);
      setResult(calcResult);
      setInput(calcResult); // Set input to result for continuous calculation
    } catch (error) {
      setResult('Error');
      setInput(''); // Clear input on error
    }
  } else if (value === 'C') {
    setInput('');
    setResult('');
  } else if (value === 'DEL') {
    setInput((prev) => prev.slice(0, -1));
  } else if (value === '%') {
    // Percentage functionality
    try {
      const percentageValue = (parseFloat(input) / 100).toString();
      setInput(percentageValue);
    } catch {
      setInput('Error');
    }
  } else {
    // Prevent multiple decimal points in a number
    if (value === '.' && input.split(/[+\-*/]/).pop().includes('.')) {
      return;
    }
    setInput((prev) => prev + value);
  }
};

