import { useState, useEffect } from 'react';
import Display from './components/Display';
import Button from './components/Button';
import { calculate } from './utils/calculate';

// ... (buttonLayout array remains the same)

export default function App() {
  const [input, setInput] = useState('');
  const [result, setResult] = useState('');

  // Map keyboard keys to calculator functions
  const handleKeyDown = (event) => {
    const { key } = event;

    // Prevent default for keys we're handling to avoid unintended behavior
    if (['Enter', 'Escape', 'Backspace', ...'0123456789/*-+.%'].includes(key)) {
      event.preventDefault();
    }

    if (key === 'Enter' || key === '=') {
      handleButtonClick('=');
    } else if (key === 'Escape' || key === 'c' || key === 'C') {
      handleButtonClick('C');
    } else if (key === 'Backspace') {
      handleButtonClick('DEL');
    } else if ('0123456789/*-+.%'.includes(key)) {
      handleButtonClick(key);
    }
  };

  // Add and cleanup the event listener
  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [input, result]); // Re-attach if input/result changes

  // handleButtonClick function from previous exercise remains the same
  const handleButtonClick = (value) => {
    // ... (previous implementation)
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 to-gray-700 flex items-center justify-center p-4">
      <div className="bg-gray-800 p-6 rounded-3xl shadow-2xl w-full max-w-xs transition-all duration-300 hover:shadow-xl">
        <Display value={input || result || '0'} />
        <div className="grid grid-cols-4 gap-3 mt-4">
          {buttonLayout.flat().map((btn) => (
            <Button 
              key={btn} 
              value={btn} 
              onClick={() => handleButtonClick(btn)}
              className={btn === '0' ? 'col-span-2' : btn === '=' ? 'col-span-2 bg-orange-500 hover:bg-orange-400' : ''}
            />
          ))}
        </div>
      </div>
    </div>
  );
}

